fn solve(x: i32) -> i32 {
    // Convert x to a string to easily extract the digit and its repetition count
    let x_str = x.to_string();
    let d = x_str.chars().next().unwrap(); // The digit as a char
    let k = x_str.len() as i32; // The number of repetitions

    // Calculate the score
    let mut score = 0;

    // Calculate the score for all digits from 1 to d
    for digit in 1..=d.to_digit(10).unwrap() {
        // For each digit, add the button presses for all its boring numbers
        score += 1; // for digit itself
        score += 2; // for dd
        score += 3; // for ddd
        score += 4; // for dddd
    }

    // Now, add the button presses for the current digit up to k
    // We only need to add the presses for the numbers d, dd, ..., up to the length k
    for length in 1..=k {
        score += length; // length of the number corresponds to the button presses
    }

    score
}